#include <cmath>
#include <algorithm>
#include <stdexcept>
#include "qtrans_runtime.hpp"

namespace implied_vol {

inline const double SIGMA_LO = 1e-06;
inline const double SIGMA_HI = 5.0;
inline const double TOL = 1e-12;
inline const long long MAX_NEWTON = 50;
inline const long long MAX_BISECT = 200;

// Declarations (so functions can call each other in any order).
double bs_price(double S, double K, double r, double sigma, double T, bool is_call);
double bs_vega(double S, double K, double r, double sigma, double T);
double implied_vol(double price, double S, double K, double r, double T, bool is_call = true);

inline double bs_price(double S, double K, double r, double sigma, double T, bool is_call) {
    double sq = sigma * std::sqrt(T);
    double a = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / sq;
    double b = a - sq;
    if (is_call) {
        return S * qt::norm_cdf(a) - K * std::exp(-r * T) * qt::norm_cdf(b);
    }
    return K * std::exp(-r * T) * qt::norm_cdf(-b) - S * qt::norm_cdf(-a);
}

inline double bs_vega(double S, double K, double r, double sigma, double T) {
    double sq = sigma * std::sqrt(T);
    double a = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / sq;
    return S * qt::norm_pdf(a) * std::sqrt(T);
}

/// Volatility sigma such that bs_price(..., sigma, ...) == price.
inline double implied_vol(double price, double S, double K, double r, double T, bool is_call) {
    if (S <= 0 || K <= 0 || T <= 0) {
        throw std::invalid_argument("S, K and T must be positive");
    }
    double disc_k = K * std::exp(-r * T);
    double lower = is_call ? std::max(S - disc_k, 0.0) : std::max(disc_k - S, 0.0);
    double upper = is_call ? S : disc_k;
    if (!(lower < price && price < upper)) {
        throw std::invalid_argument("price violates no-arbitrage bounds");
    }
    // Brenner-Subrahmanyam starting point, kept inside the bracket
    double sigma = std::sqrt(2 * qt::pi / T) * price / S;
    sigma = std::min(std::max(sigma, 0.05), 2.0);
    double lo = SIGMA_LO;
    double hi = SIGMA_HI;
    double diff = 0.0;
    for (long long _ = 0; _ < MAX_NEWTON; ++_) {
        diff = bs_price(S, K, r, sigma, T, is_call) - price;
        if (std::fabs(diff) <= TOL * price) {  // relative: an absolute test accepts anything for tiny prices
            return sigma;
        }
        // keep a bracket so bisection can take over if needed (price rises with sigma)
        if (diff > 0) {
            hi = sigma;
        } else {
            lo = sigma;
        }
        double v = bs_vega(S, K, r, sigma, T);
        if (v < 1e-10) {
            break;
        }
        double step = diff / v;
        double nxt = sigma - step;
        if (nxt <= lo || nxt >= hi) {
            break;  // Newton left the bracket
        }
        sigma = nxt;
    }
    for (long long _ = 0; _ < MAX_BISECT; ++_) {
        double mid = 0.5 * (lo + hi);
        diff = bs_price(S, K, r, mid, T, is_call) - price;
        if (std::fabs(diff) <= TOL * price || hi - lo < 1e-15) {
            return mid;
        }
        if (diff > 0) {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    throw std::runtime_error("implied volatility did not converge");
}

}  // namespace implied_vol
